BEGIN;
ALTER TABLE sessions ADD COLUMN csrf_ciphertext text;
ALTER TABLE sessions ADD COLUMN user_agent text;
ALTER TABLE plugins ADD COLUMN credential_ciphertext text;
ALTER TABLE oauth_states ADD COLUMN verifier_ciphertext text;
ALTER TABLE providers ADD COLUMN models jsonb NOT NULL DEFAULT '[]';
ALTER TABLE providers ADD COLUMN credential_ciphertext text;
ALTER TABLE files ADD COLUMN rag_status text NOT NULL DEFAULT 'pending';
ALTER TABLE files ADD COLUMN kind text;
ALTER TABLE files ADD COLUMN extracted_text text;
ALTER TABLE files ADD COLUMN page_metadata jsonb NOT NULL DEFAULT '[]';
ALTER TABLE files ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE messages ADD COLUMN user_id text REFERENCES users(id);
ALTER TABLE usage_ledger ADD COLUMN latency_ms integer;
ALTER TABLE usage_ledger ADD COLUMN ttft_ms integer;
ALTER TABLE usage_ledger ADD COLUMN status text NOT NULL DEFAULT 'completed';
ALTER TABLE usage_ledger ADD COLUMN tokens_estimated boolean NOT NULL DEFAULT false;
ALTER TABLE usage_ledger ADD COLUMN pricing_version text;
CREATE UNIQUE INDEX usage_request_once ON usage_ledger(workspace_id,request_id) WHERE request_id IS NOT NULL;
ALTER TABLE jobs ADD COLUMN actor_user_id text REFERENCES users(id);
ALTER TABLE jobs ADD COLUMN cancel_requested boolean NOT NULL DEFAULT false;
CREATE TABLE agents(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),name text NOT NULL,instructions text NOT NULL DEFAULT '',tools jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_runs(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES users(id),agent_id text REFERENCES agents(id),status text NOT NULL CHECK(status IN ('queued','planning','executing','observing','verifying','waiting_approval','completed','failed','cancelled')),objective text NOT NULL,plan jsonb NOT NULL DEFAULT '{}',state jsonb NOT NULL DEFAULT '{}',output text,error_code text,cancel_requested boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX agent_runs_workspace_page ON agent_runs(workspace_id,created_at DESC,id DESC);
CREATE TABLE tool_executions(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES users(id),run_id text REFERENCES agent_runs(id),tool_name text NOT NULL,input jsonb NOT NULL,output jsonb,status text NOT NULL,code_hash text,duration_ms integer,resource_limits jsonb,error_code text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tools_workspace_page ON tool_executions(workspace_id,created_at DESC);
CREATE TABLE approvals(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES users(id),run_id text REFERENCES agent_runs(id),tool_name text NOT NULL,input jsonb NOT NULL,input_hash text NOT NULL,status text NOT NULL CHECK(status IN ('pending','approved','rejected','consumed')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memories(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),user_id text REFERENCES users(id),conversation_id text REFERENCES conversations(id),scope text NOT NULL CHECK(scope IN ('user','workspace','conversation')),content text NOT NULL CHECK(length(content)<=2000),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,deleted_at timestamptz);
CREATE INDEX memory_scope ON memories(workspace_id,scope,user_id,created_at DESC) WHERE deleted_at IS NULL;
ALTER TABLE users ADD COLUMN memory_enabled boolean NOT NULL DEFAULT true;
CREATE TABLE artifacts(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES users(id),message_id text REFERENCES messages(id) ON DELETE SET NULL,name text NOT NULL,object_key text NOT NULL,files jsonb NOT NULL DEFAULT '[]',size_bytes bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX artifacts_workspace_page ON artifacts(workspace_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE auth_challenges(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),purpose text NOT NULL CHECK(purpose IN ('verify_email','reset_password','mfa')),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE outbox(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),job_id text NOT NULL REFERENCES jobs(id),dispatched_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox(created_at) WHERE dispatched_at IS NULL;
CREATE TABLE analyst_runs(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES users(id),plan jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
